INSERT INTO "preguntas_consulta" VALUES (1,'A','¿Esta usted de acuerdo con que se elimine la prohibicion de establecer bases militares extranjeras o instalaciones extranjeras con propositos militares y de ceder bases militares nacionales a fuerzas armadas o de seguridad extranjeras, reformando parcialmente la Constitucion de conformidad con el Anexo de la pregunta?','Bases Militares',1,'2025-11-05 20:15:13','2025-11-05 23:41:39'),(2,'B','¿Esta usted de acuerdo con que se elimine la obligacion del Estado de asignar recursos del Presupuessto General del Estado a las organizaciones politicas, reformando parcialmente la Constitucion de conformidad con el Anexo de la pregunta?','Presupuesto a Organizaciones Politicas',1,'2025-11-06 10:41:47','2025-11-06 10:44:06'),(3,'C','¿Esta usted de acuerdo con reducir el numero de asambleistas y que se los elija de acuerdo con los siguientes criterios: 10 asambleistas nacionales, 1 asambleista elegido por cada provincia: y 1 asambleista provincial adicional por cada 400.000 habitantes de acuerdo al ultimo censo nacional?','Reduccion Legislativa',1,'2025-11-06 10:44:32','2025-11-14 21:56:20'),(4,'D','¿Esta usted de acuerdo en que se convoque e instale una Asamblea Constituyente cuyos representantes sean elegidos por el pueblo ecuatoriano de acuerdo con las reglas electorales previstas en el Estatuto Constituyente adjunto, para elaborar una nueva Constitucion de la Republica, la cual entrara en vigencia unicamente si es aprobada posteriormente por las y los ecuatorianos en referemdum?','Asamblea Constituyente',1,'2025-11-06 10:44:32','2025-11-06 10:44:32');
